                      <option value="entikong" selected>PLBN Entikong (Kab. Sanggau)</option>
                      <option value="badau">PLBN Nanga Badau (Kab. Kapuas Hulu)</option>
                      <option value="aruk">PLBN Aruk (Kab. Sambas)</option>
                      <option value="lainnya">Wilayah Transit / Lainnya di Kalbar</option>
                    </select>
                    <div id="corridor-error" class="error-msg">
                      <span role="img" aria-label="Error">❌</span> Silakan pilih koridor wilayah perbatasan.
                    </div>
                  </div>

                  <div>
