                    <select id="inputCategory" name="category" required aria-describedby="category-hint"
                      data-error="category-error" class="form-control-sigap text-sm">
                      <option value="">-- Pilih Jenis Indikasi --</option>
                      <option value="Jalur Tikus / Perlintasan Ilegal">Jalur Tikus / Perlintasan Ilegal</option>
                      <option value="Perekrutan Kerja Non-Prosedural">Perekrutan Kerja Non-Prosedural</option>
                      <option value="Penampungan / Rumah Transit">Penampungan / Rumah Transit Mencurigakan</option>
                      <option value="Indikasi Online Scamming / Eksploitasi">Indikasi Online Scamming / Eksploitasi
