                        class="text-center py-2 px-2 rounded-xl border border-slate-200 text-xs font-bold text-slate-600 peer-checked:bg-slate-800 peer-checked:text-white peer-checked:border-slate-800 transition-all">
                        ⚪ Informasi Awal
                      </div>
                    </label>
                  </div>
