  <!-- Leaflet GIS JS -->
  <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>

  <script>

    // =========================================================================
    // 0. HYDRATE EMBEDDED BASE64 WEBP LOGO (SINGLE SOURCE OF TRUTH, ZERO DUPLICATION)
    // =========================================================================
    (function hydrateEmbeddedLogos() {
      const logoUri = document.getElementById('sigapFavicon')?.getAttribute('href');
      if (!logoUri) return;
      document.querySelectorAll('img[data-sigap-logo]').forEach((img) => {
        img.src = logoUri;
      });
    })();

    // =========================================================================
    // 1. MOBILE MENU TOGGLE
    // =========================================================================
    const mobileMenuBtn = document.getElementById('mobileMenuBtn');
    const mobileMenu = document.getElementById('mobileMenu');
    mobileMenuBtn.addEventListener('click', () => {
      const isHidden = mobileMenu.classList.toggle('hidden');
      mobileMenuBtn.setAttribute('aria-expanded', String(!isHidden));
    });
    function closeMobileMenu() {
      mobileMenu.classList.add('hidden');
      mobileMenuBtn.setAttribute('aria-expanded', 'false');
    }

    // =========================================================================
    // 2. NATIVE <dialog> MODAL HELPERS + LIGHT-DISMISS FALLBACK (SAFARI)
    // =========================================================================
    function openModalById(id) {
      const dlg = document.getElementById(id);
      if (dlg && typeof dlg.showModal === 'function') {
        dlg.showModal();
      }
    }

    // Fallback for browsers without native <dialog closedby="any"> support
    if (!('closedBy' in HTMLDialogElement.prototype)) {
      const isOutside = (e, dialog) => {
        const r = dialog.getBoundingClientRect();
        return e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom;
      };
      for (const dialog of document.querySelectorAll('dialog[closedby="any"]')) {
        let pressedOutside = false;
        dialog.addEventListener('pointerdown', (e) => { pressedOutside = isOutside(e, dialog); });
        dialog.addEventListener('pointerup', (e) => {
          if (pressedOutside && isOutside(e, dialog)) dialog.close();
        });
      }
    }

    // Modus Operandi detail data
    const modusData = [
      {
        badge: 'RISIKO TINGGI • JALUR LINTAS BATAS',
