        title: 'Iming-Iming Gaji Besar & Jeratan Utang',
        desc: 'Perekrut tidak resmi menawarkan pekerjaan di luar negeri dengan proses sangat cepat, tanpa pelatihan resmi, namun membebankan potongan gaji tidak wajar.',
        points: [
          'Tawaran kerja di media sosial tanpa nama PT/P3MI terdaftar di BP2MI.',
          'Identitas KTP/Paspor calon pekerja ditahan oleh perekrut atau agen.',
          'Korban dijanjikan gaji tinggi tanpa kontrak kerja tertulis yang jelas.'
        ]
      },
      {
        badge: 'TITIK TRANSIT • PENAMPUNGAN SEMENTARA',
        title: 'Rumah Penampungan Tertutup Dekat Perbatasan',
        desc: 'Sebelum diseberangkan melintasi batas negara, korban sering dikumpulkan sementara di rumah sewa atau penginapan tertutup di kecamatan perbatasan.',
        points: [
          'Penghuni berganti-ganti cepat dan dilarang berinteraksi dengan warga sekitar.',
          'Akses keluar masuk dijaga ketat oleh oknum tertentu.',
          'Aktivitas keluar-masuk kendaraan berpelat luar daerah secara tersembunyi.'
        ]
      },
      {
        badge: 'MODUS DIGITAL • EKSPLOITASI DARING',
        title: 'Online Scamming & Eksploitasi Lintas Negara',
        desc: 'Generasi muda dan pencari kerja terampil direkrut sebagai staf admin/IT di luar negeri, lalu dipaksa bekerja dalam operasi penipuan daring di bawah tekanan.',
        points: [
          'Lowongan admin/customer service luar negeri dengan syarat sangat mudah.',
          'Keberangkatan diarahkan melalui rute transit darat perbatasan Kalbar tanpa visa kerja.',
          'Komunikasi korban dengan keluarga dibatasi setelah tiba di tujuan.'
        ]
      }
    ];

    function openModusModal(idx) {
      const item = modusData[idx];
      if (!item) return;
      document.getElementById('modusBadge').textContent = item.badge;
      document.getElementById('modusDialogTitle').textContent = item.title;
      document.getElementById('modusDesc').textContent = item.desc;
      const ul = document.getElementById('modusPoints');
      ul.innerHTML = item.points.map(p => `<li>${p}</li>`).join('');
      openModalById('modusDialog');
    }

    // =========================================================================
    // 3. DATA TITIK GEO-TAGGING PERBATASAN KALIMANTAN BARAT
    //    Fokus: Entikong (Sanggau), Badau (Kapuas Hulu), Aruk (Sambas)
    // =========================================================================
    const corridorCenters = {
      all: { lat: 1.18, lng: 110.75, zoom: 8 },
      entikong: { lat: 1.0024, lng: 110.3511, zoom: 12 },
      badau: { lat: 1.0315, lng: 111.8832, zoom: 12 },
      aruk: { lat: 1.6085, lng: 109.6694, zoom: 12 }
    };

    const geoPoints = [
      {
        id: 1,
        title: 'Pos Lintas Batas Negara (PLBN) Entikong',
        corridor: 'entikong',
        corridorLabel: 'Entikong, Kab. Sanggau',
        category: 'Posko PLBN & Pengawasan Resmi',
        level: 'post',
        levelLabel: 'Posko Resmi',
        lat: 1.0024,
        lng: 110.3511,
        date: 'Aktif 24 Jam',
        desc: 'Pos pemeriksaan lintas batas resmi Indonesia–Malaysia (Tebedu). Tersedia layanan pengaduan, pendampingan BP2MI, dan koordinasi Satgas TPPO.'
      },
      {
        id: 2,
        title: 'Koridor Jalur Tikus Semanget – Entikong',
        corridor: 'entikong',
        corridorLabel: 'Entikong, Kab. Sanggau',
        category: 'Jalur Tikus / Perlintasan Ilegal',
        level: 'high',
        levelLabel: 'Rawan Tinggi',
        lat: 0.9918,
        lng: 110.3785,
        date: 'Pemantauan Riset',
        desc: 'Area perlintasan jalan kebun yang berpotensi dimanfaatkan untuk penyeberangan pekerja migran non-prosedural di luar jalur PLBN.'
      },
      {
        id: 3,
        title: 'Simpang Balai Karangan (Titik Transit)',
        corridor: 'entikong',
        corridorLabel: 'Sekayam – Entikong, Sanggau',
        category: 'Titik Transit & Penampungan',
        level: 'medium',
        levelLabel: 'Waspada',
        lat: 0.8582,
        lng: 110.4270,
        date: 'Pemantauan Riset',
        desc: 'Simpul pergerakan kendaraan menuju perbatasan Entikong yang perlu pengawasan terhadap penampungan sementara calon pekerja ilegal.'
      },
      {
        id: 4,
        title: 'Pos Lintas Batas Negara (PLBN) Nanga Badau',
        corridor: 'badau',
        corridorLabel: 'Nanga Badau, Kab. Kapuas Hulu',
        category: 'Posko PLBN & Pengawasan Resmi',
        level: 'post',
        levelLabel: 'Posko Resmi',
        lat: 1.0315,
        lng: 111.8832,
        date: 'Aktif 24 Jam',
        desc: 'Gerbang resmi perbatasan Kapuas Hulu – Lubok Antu (Sarawak). Pusat koordinasi keimigrasian dan perlindungan WNI/PMI.'
      },
      {
        id: 5,
        title: 'Jalur Kebun Perbatasan Badau – Seriang',
        corridor: 'badau',
        corridorLabel: 'Badau, Kab. Kapuas Hulu',
        category: 'Jalur Tikus / Perlintasan Ilegal',
        level: 'high',
        levelLabel: 'Rawan Tinggi',
        lat: 1.0190,
        lng: 111.9120,
        date: 'Pemantauan Riset',
        desc: 'Koridor akses perkebunan dan jalan tidak resmi yang diidentifikasi rawan aktivitas mobilisasi non-prosedural pada malam hari.'
      },
      {
        id: 6,
        title: 'Kawasan Persimpangan Lanjak – Badau',
        corridor: 'badau',
        corridorLabel: 'Batang Lupar – Badau, Kapuas Hulu',
        category: 'Perekrutan Kerja Non-Prosedural',
        level: 'medium',
        levelLabel: 'Waspada',
        lat: 0.9612,
        lng: 111.9640,
        date: 'Pemantauan Riset',
        desc: 'Jalur penghubung utama menuju Nanga Badau; fokus edukasi dan deteksi dini pergerakan rombongan tanpa dokumen resmi.'
      },
      {
        id: 7,
        title: 'Pos Lintas Batas Negara (PLBN) Aruk',
        corridor: 'aruk',
        corridorLabel: 'Sajingan Besar, Kab. Sambas',
        category: 'Posko PLBN & Pengawasan Resmi',
        level: 'post',
        levelLabel: 'Posko Resmi',
        lat: 1.6085,
        lng: 109.6694,
        date: 'Aktif 24 Jam',
        desc: 'Gerbang perbatasan utara Kalbar – Biawak (Sarawak). Menyediakan pos informasi prosedural dan bantuan darurat bagi pelintas batas.'
      },
      {
        id: 8,
        title: 'Jalur Lintas Dusun Aruk – Sajingan',
        corridor: 'aruk',
        corridorLabel: 'Sajingan Besar, Kab. Sambas',
        category: 'Jalur Tikus / Perlintasan Ilegal',
        level: 'high',
        levelLabel: 'Rawan Tinggi',
        lat: 1.5920,
        lng: 109.6440,
        date: 'Pemantauan Riset',
        desc: 'Titik rawan jalur alternatif di sekitar kawasan hutan dan ladang yang memerlukan pemantauan partisipatif warga setempat.'
      },
      {
        id: 9,
        title: 'Simpul Transit Sambas – Sajingan Besar',
        corridor: 'aruk',
        corridorLabel: 'Sambas menuju Aruk',
        category: 'Indikasi Online Scamming / Transit',
        level: 'medium',
        levelLabel: 'Waspada',
        lat: 1.4820,
        lng: 109.5150,
        date: 'Pemantauan Riset',
        desc: 'Area persinggahan calon pelintas batas menuju PLBN Aruk; prioritas sosialisasi pencegahan modus kerja ilegal & online scamming.'
      }
    ];

    // =========================================================================
    // 4. INITIALIZE MAIN GIS MAP (LEAFLET) & SIDEBAR
    // =========================================================================
    const mainMap = L.map('sigapMainMap', { scrollWheelZoom: false }).setView([1.18, 110.75], 8);

    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 18,
      attribution: '&copy; OpenStreetMap contributors | SIGAP-TPPO FT UNTAN'
    }).addTo(mainMap);

    const markerMap = new Map();
    let activeCorridorFilter = 'all';

    function createCustomPinIcon(level) {
      let iconClass = 'fa-triangle-exclamation';
      if (level === 'post') iconClass = 'fa-shield-halved';
      else if (level === 'medium') iconClass = 'fa-eye';
      else if (level === 'new-report') iconClass = 'fa-bullhorn';

      return L.divIcon({
        className: 'custom-sigap-marker',
        html: `<div class="sigap-pin ${level}"><i class="fa-solid ${iconClass}"></i></div>`,
        iconSize: [32, 32],
        iconAnchor: [16, 32],
        popupAnchor: [0, -32]
      });
    }

    function getBadgeStyle(level) {
      if (level === 'high') return 'bg-red-100 text-red-700 border-red-200';
      if (level === 'medium') return 'bg-amber-100 text-amber-800 border-amber-200';
      if (level === 'post') return 'bg-teal-100 text-teal-800 border-teal-200';
      return 'bg-[#8b0d0d] text-white border-[#5c0505]';
    }

    function renderMainMapAndSidebar() {
      // Clear markers
      markerMap.forEach(m => mainMap.removeLayer(m));
      markerMap.clear();

      const filtered = activeCorridorFilter === 'all'
        ? geoPoints
        : geoPoints.filter(p => p.corridor === activeCorridorFilter);

      document.getElementById('totalPointsCount').textContent = geoPoints.length;
      document.getElementById('visibleCountLabel').textContent = `${filtered.length} Titik`;

      const sidebar = document.getElementById('mapSidebarList');
      sidebar.innerHTML = '';

      filtered.forEach(pt => {
        // Add marker
        const marker = L.marker([pt.lat, pt.lng], { icon: createCustomPinIcon(pt.level) }).addTo(mainMap);
        marker.bindPopup(`
          <div style="font-family: 'Plus Jakarta Sans', sans-serif; min-width: 220px;">
            <div style="font-size: 10px; font-weight: 800; text-transform: uppercase; color: #8b0d0d; margin-bottom: 4px;">
              ${pt.levelLabel} &bull; ${pt.corridorLabel}
            </div>
            <div style="font-size: 14px; font-weight: 800; color: #0f172a; margin-bottom: 4px;">
              ${pt.title}
            </div>
            <div style="font-size: 11px; color: #64748b; margin-bottom: 6px;">
              <strong>Kategori:</strong> ${pt.category}
            </div>
            <p style="font-size: 12px; color: #334155; line-height: 1.45; margin: 0 0 8px 0;">
              ${pt.desc}
            </p>
            <div style="font-family: monospace; font-size: 11px; background: #fef2f2; color: #7c0a0a; padding: 4px 8px; border-radius: 6px; display: inline-block;">
              GPS: ${pt.lat.toFixed(5)}, ${pt.lng.toFixed(5)}
            </div>
          </div>
        `);
        markerMap.set(pt.id, marker);

        // Add sidebar card
        const card = document.createElement('div');
        card.className = 'map-sidebar-item';
        card.id = `sidebar-pt-${pt.id}`;
        card.innerHTML = `
          <div class="flex items-start justify-between gap-2 mb-1">
            <h4 class="text-sm font-bold text-slate-900 leading-snug">${pt.title}</h4>
            <span class="text-[10px] font-bold px-2 py-0.5 rounded-full border whitespace-nowrap ${getBadgeStyle(pt.level)}">
              ${pt.levelLabel}
            </span>
          </div>
          <p class="text-xs text-slate-500 mb-2">
            <i class="fa-solid fa-location-dot text-[#8b0d0d] mr-1"></i>${pt.corridorLabel}
          </p>
          <div class="flex items-center justify-between text-[11px]">
            <span class="font-mono bg-red-50 text-[#8b0d0d] font-bold px-2 py-0.5 rounded border border-red-100">
              ${pt.lat.toFixed(4)}, ${pt.lng.toFixed(4)}
            </span>
            <span class="text-slate-400 font-semibold">${pt.date}</span>
          </div>
        `;
        card.addEventListener('click', () => focusPointOnMainMap(pt.id));
        sidebar.appendChild(card);
      });
    }

    function focusPointOnMainMap(id) {
      const pt = geoPoints.find(p => p.id === id);
      const marker = markerMap.get(id);
      if (!pt || !marker) return;

      document.querySelectorAll('.map-sidebar-item').forEach(el => el.classList.remove('active'));
      const activeEl = document.getElementById(`sidebar-pt-${id}`);
      if (activeEl) {
        activeEl.classList.add('active');
        activeEl.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }

      mainMap.flyTo([pt.lat, pt.lng], 13, { duration: 0.9 });
      setTimeout(() => marker.openPopup(), 450);
    }

    function filterMapCorridor(corridor, btnEl) {
      activeCorridorFilter = corridor;
      document.querySelectorAll('.filter-corridor-btn').forEach(btn => {
        const isCurrent = btn.dataset.corridor === corridor;
        btn.classList.toggle('bg-[#8b0d0d]', isCurrent);
        btn.classList.toggle('text-white', isCurrent);
        btn.classList.toggle('bg-red-50', !isCurrent);
        btn.classList.toggle('text-[#8b0d0d]', !isCurrent);
      });

      renderMainMapAndSidebar();
      const target = corridorCenters[corridor] || corridorCenters.all;
      mainMap.flyTo([target.lat, target.lng], target.zoom, { duration: 0.8 });
    }

    function focusCorridorFromHero(corridor) {
      document.getElementById('map-section').scrollIntoView({ behavior: 'smooth' });
      const btn = document.querySelector(`.filter-corridor-btn[data-corridor="${corridor}"]`);
      filterMapCorridor(corridor, btn);
    }

    renderMainMapAndSidebar();

    // =========================================================================
    // 5. INTERACTIVE MAP PICKER FOR QUICK REPORT FORM (#lapor-section)
    // =========================================================================
    const pickerMap = L.map('pickerMap').setView([1.0024, 110.3511], 11);
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 18,
      attribution: '&copy; OpenStreetMap'
    }).addTo(pickerMap);

    const pickerMarker = L.marker([1.0024, 110.3511], {
      draggable: true,
      icon: createCustomPinIcon('high')
    }).addTo(pickerMap);

    function detectNearestCorridor(lat, lng) {
      const dist = (a, b) => Math.hypot(lat - a, lng - b);
      const dEntikong = dist(1.0024, 110.3511);
      const dBadau = dist(1.0315, 111.8832);
      const dAruk = dist(1.6085, 109.6694);
      const min = Math.min(dEntikong, dBadau, dAruk);
      if (min > 0.85) return { code: 'lainnya', label: 'Wilayah Kalbar Lainnya' };
      if (min === dEntikong) return { code: 'entikong', label: 'Koridor Entikong, Sanggau' };
      if (min === dBadau) return { code: 'badau', label: 'Koridor Nanga Badau, Kapuas Hulu' };
      return { code: 'aruk', label: 'Koridor Aruk, Sambas' };
    }

    function updatePickerCoordinates(lat, lng, customLabel) {
      const latStr = lat.toFixed(6);
      const lngStr = lng.toFixed(6);

      document.getElementById('inputLat').value = latStr;
      document.getElementById('inputLng').value = lngStr;
      document.getElementById('pickerCoordBadge').textContent = `${latStr}, ${lngStr}`;

      const nearest = detectNearestCorridor(lat, lng);
      document.getElementById('pickerStatusText').textContent = `Titik terpilih: ${customLabel || nearest.label}`;
      const corridorSelect = document.getElementById('inputCorridor');
      if (corridorSelect) {
        corridorSelect.value = nearest.code;
        syncAria(corridorSelect);
      }
    }

    pickerMap.on('click', (e) => {
      const { lat, lng } = e.latlng;
      pickerMarker.setLatLng([lat, lng]);
      updatePickerCoordinates(lat, lng);
    });

    pickerMarker.on('dragend', () => {
      const { lat, lng } = pickerMarker.getLatLng();
      updatePickerCoordinates(lat, lng);
    });

    function centerPickerTo(lat, lng, corridorCode, label) {
      pickerMap.flyTo([lat, lng], 12, { duration: 0.7 });
      pickerMarker.setLatLng([lat, lng]);
      updatePickerCoordinates(lat, lng, label);
      document.getElementById('inputCorridor').value = corridorCode;
    }

    function useCurrentGps() {
      const btn = document.getElementById('btnUseMyGps');
      if (!navigator.geolocation) {
        alert('Peramban Anda tidak mendukung Geolocation GPS. Silakan klik langsung titik pada peta.');
        return;
      }
      btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> <span>Mencari GPS...</span>';
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          const { latitude, longitude } = pos.coords;
          pickerMap.flyTo([latitude, longitude], 14, { duration: 0.8 });
          pickerMarker.setLatLng([latitude, longitude]);
          updatePickerCoordinates(latitude, longitude, 'Lokasi GPS Perangkat Anda');
          btn.innerHTML = '<i class="fa-solid fa-check"></i> <span>GPS Terkunci</span>';
          setTimeout(() => {
            btn.innerHTML = '<i class="fa-solid fa-location-crosshairs"></i> <span>Ambil GPS Saya</span>';
          }, 2500);
        },
        () => {
          btn.innerHTML = '<i class="fa-solid fa-location-crosshairs"></i> <span>Ambil GPS Saya</span>';
          alert('Akses GPS tidak diizinkan atau tidak tersedia. Silakan klik langsung titik pada peta atau pilih tombol Entikong / Badau / Aruk.');
        },
        { enableHighAccuracy: true, timeout: 8000 }
      );
    }

    // Toggle identity fields when Anonymous checkbox changes
    function toggleReporterIdentity() {
      const isAnon = document.getElementById('chkAnonymous').checked;
      document.getElementById('identityFields').classList.toggle('hidden', isAnon);
    }

    // =========================================================================
    // 6. ACCESSIBLE FORM VALIDATION (:user-invalid + ARIA SYNC)
    //    Following Modern Web Guidance: validate-input-after-interaction
    // =========================================================================
    const reportForm = document.getElementById('quickReportForm');

    const linkError = (el, shown) => {
      const errorId = el.dataset.error;
      if (!errorId) return;
      const ids = (el.getAttribute('aria-describedby') || '').split(/\s+/).filter(id => id && id !== errorId);
      if (shown) ids.push(errorId);
      if (ids.length) el.setAttribute('aria-describedby', ids.join(' '));
      else el.removeAttribute('aria-describedby');
    };

    const announcer = document.createElement('div');
    announcer.setAttribute('aria-live', 'polite');
    announcer.classList.add('visually-hidden');
    document.body.append(announcer);
    let announceTimer;

    const announceError = (el) => {
      const errEl = document.getElementById(el.dataset.error);
      if (!errEl) return;
      clearTimeout(announceTimer);
      announcer.textContent = '';
      announceTimer = setTimeout(() => {
        announcer.textContent = errEl.textContent.trim();
      }, 450);
    };

    const supportsUserInvalid = CSS.supports('selector(:user-invalid)');
    const syncAria = (el, announce = false) => {
      if (!el?.matches?.('input, select, textarea')) return;
      const invalid = supportsUserInvalid
        ? el.matches(':user-invalid')
        : el.classList.contains('user-invalid-fallback');

      el.setAttribute('aria-invalid', invalid ? 'true' : 'false');
      linkError(el, invalid);
      if (invalid && announce) announceError(el);
    };

    reportForm.querySelectorAll('input, select, textarea').forEach(el => {
      el.setAttribute('aria-invalid', 'false');
    });

    reportForm.addEventListener('blur', (e) => {
      if (!supportsUserInvalid && e.target.checkValidity) {
        e.target.classList.toggle('user-invalid-fallback', !e.target.validity.valid);
      }
      syncAria(e.target, true);
    }, true);

    reportForm.addEventListener('input', (e) => {
      if (!supportsUserInvalid && e.target.classList.contains('user-invalid-fallback')) {
        e.target.classList.toggle('user-invalid-fallback', !e.target.validity.valid);
      }
      syncAria(e.target);
    });

    reportForm.addEventListener('change', (e) => {
      if (!supportsUserInvalid && e.target.checkValidity) {
        e.target.classList.toggle('user-invalid-fallback', !e.target.validity.valid);
      }
      syncAria(e.target, true);
    }, true);

    // Handle Form Submission -> Add Live Pin to Main Map + Show Ticket Dialog
    let latestAddedPointId = null;

    reportForm.addEventListener('submit', (e) => {
      e.preventDefault();

      // Trigger constraint validation cleanly across all required controls
      const controls = [...reportForm.querySelectorAll('input[required], select[required], textarea[required]')];
      let firstInvalid = null;

      controls.forEach(ctrl => {
        if (!ctrl.validity.valid) {
          ctrl.classList.add('user-invalid-fallback');
          ctrl.setAttribute('aria-invalid', 'true');
          linkError(ctrl, true);
          if (!firstInvalid) firstInvalid = ctrl;
        } else {
          ctrl.classList.remove('user-invalid-fallback');
          ctrl.setAttribute('aria-invalid', 'false');
          linkError(ctrl, false);
        }
      });

      if (firstInvalid) {
        firstInvalid.focus();
        announceError(firstInvalid);
        return;
      }

      // Collect report data
      const lat = parseFloat(document.getElementById('inputLat').value);
      const lng = parseFloat(document.getElementById('inputLng').value);
      const corridor = document.getElementById('inputCorridor').value;
      const corridorText = document.getElementById('inputCorridor').selectedOptions[0].textContent;
      const category = document.getElementById('inputCategory').value;
      const title = document.getElementById('inputTitle').value.trim();
      const desc = document.getElementById('inputDesc').value.trim();
      const urgency = reportForm.querySelector('input[name="urgency"]:checked')?.value || 'high';
      const isAnon = document.getElementById('chkAnonymous').checked;
      const reporterName = document.getElementById('inputName').value.trim();

      const ticketId = `SIGAP-2026-${String(Math.floor(1000 + Math.random() * 9000))}`;
      const newId = Date.now();
      latestAddedPointId = newId;

      // Push new live geotagged report into main map points
      geoPoints.unshift({
        id: newId,
        title: title,
        corridor: corridor === 'lainnya' ? 'entikong' : corridor,
        corridorLabel: corridorText,
        category: category,
        level: 'new-report',
        levelLabel: urgency === 'high' ? 'Laporan Baru (Darurat)' : 'Laporan Baru',
        lat: lat,
        lng: lng,
        date: 'Baru Saja',
        desc: `${desc} [Tiket: ${ticketId} • ${isAnon ? 'Pelapor Anonim' : (reporterName || 'Pelapor Terdaftar')}]`
      });

      // Re-render map in 'all' view so user sees their new point immediately
      const allBtn = document.querySelector('.filter-corridor-btn[data-corridor="all"]');
      filterMapCorridor('all', allBtn);

      // Populate ticket modal
      document.getElementById('ticketCode').textContent = ticketId;
      document.getElementById('ticketLocation').textContent = `${title} (${corridorText})`;
      document.getElementById('ticketCoords').textContent = `${lat.toFixed(5)}, ${lng.toFixed(5)}`;
      document.getElementById('ticketPrivacy').textContent = isAnon
        ? 'Anonim (Identitas Dirahasiakan)'
        : `Terdaftar (${reporterName || 'Kontak Pelapor'})`;

      // Reset text fields (keep map pin intact)
      document.getElementById('inputTitle').value = '';
      document.getElementById('inputDesc').value = '';
      document.getElementById('inputPhoto').value = '';
      controls.forEach(c => {
        c.classList.remove('user-invalid-fallback', 'user-valid-fallback');
        c.setAttribute('aria-invalid', 'false');
        linkError(c, false);
      });

      openModalById('ticketDialog');
    });

    document.getElementById('btnViewNewPointOnMap').addEventListener('click', () => {
      document.getElementById('ticketDialog').close();
      document.getElementById('map-section').scrollIntoView({ behavior: 'smooth' });
      if (latestAddedPointId) {
        setTimeout(() => focusPointOnMainMap(latestAddedPointId), 450);
      }
    });
  </script>

</body>

